\version "2.27.2"
% automatically converted by musicxml2ly from 72c-TransposingInstruments-Change.xml
\pointAndClickOff

\header {
  texidoc = "An instrument change from one transposition (Clarinet in Eb) to
    another transposing instrument (Clarinet in Bb). The displayed instrument
    name should also be updated.

    The whole piece is in Bb major (sounding), so first the key signature should
    be one flat, after the change it should have no accidentals.

    Both the instrument name and instrument name abbreviation use the
    <accidental-text> element to display a proper ‘flat’ glyph."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key g \major \transposition es' c1 | % 1
  \key c \major \transposition bes \set Staff.instrumentName = \markup \concat {
    "Clarinet in B" \tiny \number "♭" } \set Staff.shortInstrumentName = \markup
  \concat { "Cl. (B" \tiny \number "♭" ")" } c1 \break | % 2
  c1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \set Staff.instrumentName = \markup \concat { "Clarinet in E" \tiny
        \number "♭" }
      \set Staff.shortInstrumentName = \markup \concat { "Cl. (E" \tiny \number
        "♭" ")" }
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
